import React, { useState, useEffect, useMemo, useCallback } from "react";
import { Phone, MapPin, Car, Calendar as CalIcon, CheckSquare, Square, Settings, ChevronLeft, ChevronRight, Sparkles, Crosshair, X, Check, Plus, Minus, Users } from "lucide-react";
import { fetchConfig, saveConfig as saveConfigDb, fetchBookedSlots, toggleSlot as toggleSlotDb, addReservation, addSubscription } from "./db.js";

/* ============================== DESIGN TOKENS ==============================
   Palette dérivée du logo WashGo :
   - navy      #0B1E3D  (silhouette voiture / wordmark "Wash")
   - navyDeep  #071427  (fonds profonds)
   - blue      #1C6FEF  (bleu primaire du dégradé)
   - blueBright#29B6F6  (bleu clair, éclats/étoiles)
   - ice       #F4F8FD  (fond app, quasi blanc bleuté)
   - slate     #64748B  (texte secondaire)
   - mist      #E7EFFB  (bordures, fonds de cartes inactives)
================================================================================ */

const T = {
  navy: "#0B1E3D",
  navyDeep: "#071427",
  blue: "#1C6FEF",
  blueBright: "#29B6F6",
  ice: "#F4F8FD",
  slate: "#64748B",
  mist: "#E7EFFB",
  white: "#FFFFFF",
  danger: "#E24C4C",
  gradient: "linear-gradient(135deg, #0B1E3D 0%, #1C6FEF 60%, #29B6F6 100%)",
};

const LOGO_MED = "data:image/png;base64,";
const LOGO_SMALL = "data:image/png;base64,";

const SLOTS = ["07h00-08h30","08h30-10h00","10h00-11h30","11h30-13h00","13h00-14h30","14h30-16h00","16h00-17h30","17h30-19h00"];

const SERVICES = [
  { id: "ext", label: "Lavage extérieur", key: "exterieur" },
  { id: "int", label: "Lavage intérieur", key: "interieur" },
  { id: "complet", label: "Lavage complet", key: "complet" },
  { id: "vapeur", label: "Traitement à la vapeur", key: "vapeur" },
  { id: "plastique", label: "Rénovation des plastiques", key: "plastique" },
  { id: "pneus", label: "Brillance des pneus", key: "pneus" },
  { id: "vitres", label: "Traitement des vitres", key: "vitres" },
];

const DEFAULT_PRICES = {
  exterieur: 3000, interieur: 3000, complet: 5000, vapeur: 4000,
  plastique: 3500, pneus: 1500, vitres: 1500,
};

const VEHICLES = [
  { id: "petit", label: "Petit véhicule", mult: 1, hint: "Citadine, berline compacte" },
  { id: "moyen", label: "Véhicule moyen", mult: 1.15, hint: "Berline, monospace" },
  { id: "grand", label: "Grand véhicule", mult: 1.3, hint: "SUV, 4x4, utilitaire" },
];

const SUB_PLANS = [
  { id: 2, label: "2 passages / mois", discount: 0.05 },
  { id: 4, label: "4 passages / mois", discount: 0.10 },
  { id: 8, label: "8 passages / mois", discount: 0.15 },
];

const fmt = (n) => Math.round(n).toLocaleString("fr-FR") + " FCFA";
const todayISO = () => new Date().toISOString().slice(0, 10);
const addDays = (iso, d) => {
  const dt = new Date(iso + "T00:00:00");
  dt.setDate(dt.getDate() + d);
  return dt.toISOString().slice(0, 10);
};
const slotStartMinutes = (slot) => {
  const [start] = slot.split("-");
  const [h, m] = start.replace("h", ":").split(":").map(Number);
  return h * 60 + m;
};
const isSlotPast = (dateISO, slot) => {
  if (dateISO !== todayISO()) return false;
  const now = new Date();
  return slotStartMinutes(slot) <= now.getHours() * 60 + now.getMinutes();
};
const dayLabel = (iso) => {
  const dt = new Date(iso + "T00:00:00");
  const wd = dt.toLocaleDateString("fr-FR", { weekday: "short" }).replace(".", "");
  const dNum = dt.getDate();
  const mo = dt.toLocaleDateString("fr-FR", { month: "short" }).replace(".", "");
  return { wd: wd.charAt(0).toUpperCase() + wd.slice(1), dNum, mo };
};

/* ============================== SMALL UI PRIMITIVES ============================== */

function FontStyles() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
      .wg-root, .wg-root * { box-sizing: border-box; font-family: 'Inter', sans-serif; }
      .wg-display { font-family: 'Sora', sans-serif; }
      .wg-scrollx::-webkit-scrollbar { display: none; }
      .wg-scrollx { -ms-overflow-style: none; scrollbar-width: none; }
      @keyframes wg-rise { from { opacity: 0; transform: translateY(10px);} to { opacity:1; transform: translateY(0);} }
      .wg-anim { animation: wg-rise .28s ease both; }
      @keyframes wg-pulse { 0%,100%{ transform: scale(1);} 50%{ transform: scale(1.04);} }
      .wg-pulse { animation: wg-pulse 2.2s ease-in-out infinite; }
    `}</style>
  );
}

function TopBar({ title, onBack, onSettings }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "16px 18px", background: T.navy, color: T.white,
    }}>
      <div style={{ width: 34 }}>
        {onBack && (
          <button onClick={onBack} aria-label="Retour" style={{
            background: "rgba(255,255,255,0.12)", border: "none", borderRadius: 10,
            width: 34, height: 34, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
          }}>
            <ChevronLeft size={18} color={T.white} />
          </button>
        )}
      </div>
      <div className="wg-display" style={{ fontSize: 16, fontWeight: 700, letterSpacing: 0.2 }}>{title}</div>
      <div style={{ width: 34 }}>
        {onSettings && (
          <button onClick={onSettings} aria-label="Réglages" style={{
            background: "rgba(255,255,255,0.12)", border: "none", borderRadius: 10,
            width: 34, height: 34, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
          }}>
            <Settings size={17} color={T.white} />
          </button>
        )}
      </div>
    </div>
  );
}

function ProgressDots({ step, total }) {
  return (
    <div style={{ display: "flex", gap: 6, justifyContent: "center", padding: "12px 0 4px" }}>
      {Array.from({ length: total }).map((_, i) => (
        <div key={i} style={{
          height: 6, borderRadius: 4, transition: "all .25s",
          width: i === step ? 22 : 6,
          background: i <= step ? T.blue : T.mist,
        }} />
      ))}
    </div>
  );
}

function PrimaryButton({ children, onClick, disabled, style }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      width: "100%", border: "none", borderRadius: 14, padding: "15px 18px",
      background: disabled ? T.mist : T.gradient, color: disabled ? "#9FB0C6" : T.white,
      fontWeight: 700, fontSize: 15, cursor: disabled ? "not-allowed" : "pointer",
      boxShadow: disabled ? "none" : "0 8px 20px -8px rgba(28,111,239,0.55)",
      display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
      transition: "transform .12s", ...style,
    }}
    onMouseDown={(e) => { if (!disabled) e.currentTarget.style.transform = "scale(0.98)"; }}
    onMouseUp={(e) => { e.currentTarget.style.transform = "scale(1)"; }}
    >
      {children}
    </button>
  );
}

function SecondaryButton({ children, onClick, style }) {
  return (
    <button onClick={onClick} style={{
      width: "100%", borderRadius: 14, padding: "14px 18px",
      background: T.white, color: T.navy, fontWeight: 700, fontSize: 15,
      border: `1.5px solid ${T.mist}`, cursor: "pointer", ...style,
    }}>
      {children}
    </button>
  );
}

function TextField({ label, icon, ...props }) {
  return (
    <label style={{ display: "block", marginBottom: 14 }}>
      <div style={{ fontSize: 12.5, fontWeight: 600, color: T.slate, marginBottom: 6 }}>{label}</div>
      <div style={{
        display: "flex", alignItems: "center", gap: 8, border: `1.5px solid ${T.mist}`,
        borderRadius: 12, padding: "12px 14px", background: T.white,
      }}>
        {icon}
        <input {...props} style={{ border: "none", outline: "none", fontSize: 14.5, width: "100%", background: "transparent", color: T.navy }} />
      </div>
    </label>
  );
}

function Screen({ children }) {
  return <div className="wg-anim" style={{ padding: "18px 18px 110px" }}>{children}</div>;
}

/* ============================== APP ============================== */

export default function WashGoApp() {
  const [screen, setScreen] = useState("home");
  const [prices, setPrices] = useState(DEFAULT_PRICES);
  const [waNumber, setWaNumber] = useState("");
  const [trustCount, setTrustCount] = useState(500);
  const [adminPin, setAdminPin] = useState("Platini10@");
  const [showPinGate, setShowPinGate] = useState(false);
  const [configLoaded, setConfigLoaded] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  useEffect(() => {
    const blockContextMenu = (e) => e.preventDefault();
    document.addEventListener("contextmenu", blockContextMenu);
    return () => document.removeEventListener("contextmenu", blockContextMenu);
  }, []);
  const [toast, setToast] = useState(null);

  const [booking, setBooking] = useState({
    phone: "", addrType: "cite", cityRes: "", unitNumber: "", gps: null,
    vehicle: null, date: todayISO(), time: null, services: [],
  });
  const [bookedSlots, setBookedSlots] = useState({}); // { dateISO: [times booked] }

  const [sub, setSub] = useState({
    phone: "", addrType: "cite", cityRes: "", unitNumber: "",
    plan: null, passages: [],
  });
  const [subStep, setSubStep] = useState(0);
  const [passageEditing, setPassageEditing] = useState(0);

  useEffect(() => {
    (async () => {
      try {
        const parsed = await fetchConfig();
        if (parsed) {
          setPrices({ ...DEFAULT_PRICES, ...parsed.prices });
          setWaNumber(parsed.waNumber || "");
          setTrustCount(parsed.trustCount ?? 500);
          setAdminPin(parsed.adminPin || "Platini10@");
        }
      } catch (e) { /* pas de config existante, ou Supabase indisponible */ }
      setConfigLoaded(true);
    })();
  }, []);

  const loadSlotsForDate = useCallback(async (dateISO) => {
    try {
      const arr = await fetchBookedSlots(dateISO);
      setBookedSlots((prev) => ({ ...prev, [dateISO]: arr }));
    } catch (e) {
      setBookedSlots((prev) => ({ ...prev, [dateISO]: [] }));
    }
  }, []);

  useEffect(() => {
    if (screen === "r-date") {
      for (let i = 0; i < 14; i++) {
        const d = addDays(todayISO(), i);
        if (bookedSlots[d] === undefined) loadSlotsForDate(d);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screen]);

  const adminToggleSlot = async (dateISO, slot) => {
    const current = bookedSlots[dateISO] || [];
    const wasBooked = current.includes(slot);
    let lastError = null;
    for (let attempt = 0; attempt < 4; attempt++) {
      try {
        const updated = await toggleSlotDb(dateISO, slot, wasBooked);
        setBookedSlots((prev) => ({ ...prev, [dateISO]: updated }));
        showToast(wasBooked ? "Créneau libéré" : "Créneau marqué réservé");
        return;
      } catch (e) {
        lastError = e;
        await new Promise((r) => setTimeout(r, 500 * (attempt + 1)));
      }
    }
    showToast("La base de données est momentanément indisponible. Réessayez dans un instant.");
  };

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(null), 2600); };

  const saveConfig = async (nextPrices, nextWa, nextTrust, nextPin) => {
    try {
      await saveConfigDb({ prices: nextPrices, waNumber: nextWa, trustCount: nextTrust, adminPin: nextPin });
      showToast("Réglages enregistrés");
    } catch (e) { showToast("Erreur d'enregistrement"); }
  };

  const bookingTotal = useMemo(() => {
    const mult = VEHICLES.find((v) => v.id === booking.vehicle)?.mult || 1;
    const base = booking.services.reduce((sum, id) => {
      const svc = SERVICES.find((s) => s.id === id);
      return sum + (prices[svc.key] || 0);
    }, 0);
    return Math.round(base * mult);
  }, [booking.services, booking.vehicle, prices]);

  const resetBooking = () => setBooking({
    phone: "", addrType: "cite", cityRes: "", unitNumber: "", gps: null,
    vehicle: null, date: todayISO(), time: null, services: [],
  });

  const goHome = () => { resetBooking(); setSub({ phone: "", addrType: "cite", cityRes: "", unitNumber: "", plan: null, passages: [] }); setSubStep(0); setScreen("home"); };

  const bookingWaMessage = useMemo(() => {
    const total = bookingTotal;
    const acompte = Math.round(total * 0.5);
    const svcLabels = booking.services.map((id) => SERVICES.find((s) => s.id === id).label).join(", ");
    const addrLine = booking.addrType === "cite"
      ? `Cité: ${booking.cityRes} — Villa n°${booking.unitNumber}`
      : `Résidence: ${booking.cityRes} — Appt n°${booking.unitNumber}`;
    const gpsLine = booking.gps ? `\nLocalisation GPS: ${booking.gps.lat.toFixed(5)}, ${booking.gps.lng.toFixed(5)}` : "";
    const vLabel = VEHICLES.find((v) => v.id === booking.vehicle)?.label;
    return `Nouvelle réservation WashGo
Numéro client: ${booking.phone}
Adresse: ${addrLine}${gpsLine}
Type de véhicule: ${vLabel}
Date: ${booking.date}
Heure: ${booking.time}
Prestations: ${svcLabels}
Total: ${fmt(total)}
Acompte demandé (50%): ${fmt(acompte)}`;
  }, [booking, bookingTotal]);

  const bookingWaUrl = useMemo(
    () => `https://wa.me/${waNumber.replace(/\D/g, "")}?text=${encodeURIComponent(bookingWaMessage)}`,
    [bookingWaMessage, waNumber]
  );

  const saveBooking = async () => {
    const total = bookingTotal;
    const acompte = Math.round(total * 0.5);
    try {
      await addReservation(booking, total, acompte);
    } catch (e) { /* base indisponible — on continue quand même */ }
    setScreen("r-done");
  };

  const passageTotal = (svcIds) => svcIds.reduce((sum, id) => {
    const svc = SERVICES.find((s) => s.id === id);
    return sum + (prices[svc.key] || 0);
  }, 0);

  const subTotal = useMemo(() => {
    if (!sub.plan) return 0;
    const plan = SUB_PLANS.find((p) => p.id === sub.plan);
    const raw = sub.passages.reduce((sum, p) => sum + passageTotal(p.services || []), 0);
    return Math.round(raw * (1 - (plan?.discount || 0)));
  }, [sub, prices]);

  const subWaMessage = useMemo(() => {
    const plan = SUB_PLANS.find((p) => p.id === sub.plan);
    if (!plan) return "";
    const addrLine = sub.addrType === "cite"
      ? `Cité: ${sub.cityRes} — Villa n°${sub.unitNumber}`
      : `Résidence: ${sub.cityRes} — Appt n°${sub.unitNumber}`;
    const passagesLines = sub.passages.map((p, i) =>
      `Passage ${i + 1}: ${(p.services || []).map((id) => SERVICES.find((s) => s.id === id).label).join(" + ") || "—"}`
    ).join("\n");
    return `Nouvel abonnement WashGo
Numéro client: ${sub.phone}
Adresse: ${addrLine}
Formule: ${plan.label}
${passagesLines}
Total mensuel: ${fmt(subTotal)}`;
  }, [sub, subTotal]);

  const subWaUrl = useMemo(
    () => `https://wa.me/${waNumber.replace(/\D/g, "")}?text=${encodeURIComponent(subWaMessage)}`,
    [subWaMessage, waNumber]
  );

  const saveSub = async () => {
    try {
      await addSubscription(sub, subTotal);
    } catch (e) { /* base indisponible */ }
    setScreen("s-done");
  };

  return (
    <div className="wg-root" style={{
      maxWidth: 430, margin: "0 auto", minHeight: 760, background: T.ice,
      borderRadius: 28, overflow: "hidden", boxShadow: "0 30px 60px -20px rgba(11,30,61,0.35)",
      border: `1px solid ${T.mist}`, position: "relative", fontFamily: "Inter, sans-serif",
    }}>
      <FontStyles />

      {screen === "home" && (
        <HomeScreen onReserve={() => setScreen("r-phone")} onSub={() => setScreen("s-plan")} onSettings={() => setShowPinGate(true)} trustCount={trustCount} />
      )}

      {screen === "r-phone" && (
        <>
          <TopBar title="Réservation" onBack={goHome} />
          <ProgressDots step={0} total={5} />
          <Screen>
            <StepLabel n={1} text="Vos informations" />
            <TextField label="Numéro de téléphone" icon={<Phone size={16} color={T.slate} />}
              placeholder="Ex: 07 00 00 00 00" value={booking.phone}
              onChange={(e) => setBooking({ ...booking, phone: e.target.value })} />
            <PrimaryButton disabled={booking.phone.trim().length < 8} onClick={() => setScreen("r-addr")}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "r-addr" && (
        <>
          <TopBar title="Réservation" onBack={() => setScreen("r-phone")} />
          <ProgressDots step={1} total={5} />
          <Screen>
            <StepLabel n={2} text="Votre adresse" />
            <AddressForm data={booking} setData={setBooking} />
            <PrimaryButton disabled={!booking.cityRes || !booking.unitNumber} onClick={() => setScreen("r-vehicle")}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "r-vehicle" && (
        <>
          <TopBar title="Réservation" onBack={() => setScreen("r-addr")} />
          <ProgressDots step={2} total={5} />
          <Screen>
            <StepLabel n={3} text="Type de véhicule" />
            {VEHICLES.map((v) => (
              <VehicleCard key={v.id} v={v} selected={booking.vehicle === v.id}
                onClick={() => setBooking({ ...booking, vehicle: v.id })} />
            ))}
            <PrimaryButton disabled={!booking.vehicle} onClick={() => setScreen("r-date")} style={{ marginTop: 6 }}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "r-date" && (
        <>
          <TopBar title="Réservation" onBack={() => setScreen("r-vehicle")} />
          <ProgressDots step={3} total={5} />
          <Screen>
            <StepLabel n={4} text="Date et heure" />
            <DatePicker booking={booking} setBooking={setBooking} bookedSlots={bookedSlots} />
            <div style={{ fontSize: 12.5, fontWeight: 600, color: T.slate, margin: "18px 0 8px" }}>Créneau disponible</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              {SLOTS.map((s) => {
                const taken = (bookedSlots[booking.date] || []).includes(s) || isSlotPast(booking.date, s);
                const selected = booking.time === s;
                return (
                  <button key={s} disabled={taken}
                    onClick={() => setBooking({ ...booking, time: s })}
                    style={{
                      padding: "11px 8px", borderRadius: 12, fontSize: 13, fontWeight: 600,
                      border: `1.5px solid ${taken ? "#EEF1F5" : selected ? T.blue : T.mist}`,
                      background: taken ? "#F7F8FA" : selected ? "rgba(28,111,239,0.08)" : T.white,
                      color: taken ? "#C7CED9" : selected ? T.blue : T.navy,
                      cursor: taken ? "not-allowed" : "pointer",
                      pointerEvents: taken ? "none" : "auto",
                    }}>
                    {s}
                  </button>
                );
              })}
            </div>
            <PrimaryButton disabled={!booking.time} onClick={() => setScreen("r-services")} style={{ marginTop: 20 }}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "r-services" && (
        <>
          <TopBar title="Réservation" onBack={() => setScreen("r-date")} />
          <ProgressDots step={4} total={5} />
          <Screen>
            <StepLabel n={5} text="Prestations souhaitées" />
            <ServicesList selected={booking.services} prices={prices}
              onToggle={(id) => setBooking((b) => ({
                ...b, services: b.services.includes(id) ? b.services.filter((s) => s !== id) : [...b.services, id],
              }))} />
          </Screen>
          {booking.services.length > 0 && (
            <TotalBar total={bookingTotal} acompte={Math.round(bookingTotal * 0.5)} href={bookingWaUrl} onConfirm={saveBooking} label="Réserver via WhatsApp" />
          )}
        </>
      )}

      {screen === "r-done" && (
        <ConfirmScreen
          title="Réservation envoyée !"
          text="Votre demande a été préparée sur WhatsApp. Confirmez l'envoi du message pour finaliser votre réservation."
          onHome={goHome}
        />
      )}

      {/* ============ ABONNEMENT ============ */}

      {screen === "s-plan" && (
        <>
          <TopBar title="Abonnement WashGo" onBack={goHome} />
          <ProgressDots step={0} total={3} />
          <Screen>
            <StepLabel n={1} text="Choisissez votre formule" />
            {SUB_PLANS.map((p) => (
              <PlanCard key={p.id} plan={p} selected={sub.plan === p.id}
                onClick={() => setSub({ ...sub, plan: p.id, passages: Array.from({ length: p.id }, () => ({ services: [] })) })} />
            ))}
            <PrimaryButton disabled={!sub.plan} onClick={() => setScreen("s-info")} style={{ marginTop: 6 }}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "s-info" && (
        <>
          <TopBar title="Abonnement WashGo" onBack={() => setScreen("s-plan")} />
          <ProgressDots step={1} total={3} />
          <Screen>
            <StepLabel n={2} text="Vos informations" />
            <TextField label="Numéro de téléphone" icon={<Phone size={16} color={T.slate} />}
              placeholder="Ex: 07 00 00 00 00" value={sub.phone}
              onChange={(e) => setSub({ ...sub, phone: e.target.value })} />
            <AddressForm data={sub} setData={setSub} hideGps />
            <PrimaryButton disabled={sub.phone.trim().length < 8 || !sub.cityRes || !sub.unitNumber}
              onClick={() => setScreen("s-passages")}>
              Continuer <ChevronRight size={16} />
            </PrimaryButton>
          </Screen>
        </>
      )}

      {screen === "s-passages" && (
        <>
          <TopBar title="Abonnement WashGo" onBack={() => setScreen("s-info")} />
          <ProgressDots step={2} total={3} />
          <Screen>
            <StepLabel n={3} text="Prestations par passage" />
            <div style={{ fontSize: 13, color: T.slate, marginBottom: 14, lineHeight: 1.5 }}>
              Personnalisez les prestations souhaitées pour chacun de vos {sub.plan} passages mensuels.
            </div>
            {sub.passages.map((p, i) => (
              <PassageRow key={i} index={i} services={p.services}
                open={passageEditing === i}
                onOpen={() => setPassageEditing(passageEditing === i ? -1 : i)}
                prices={prices}
                onToggle={(id) => {
                  const next = [...sub.passages];
                  const cur = next[i].services;
                  next[i] = { services: cur.includes(id) ? cur.filter((s) => s !== id) : [...cur, id] };
                  setSub({ ...sub, passages: next });
                }} />
            ))}
          </Screen>
          {sub.passages.some((p) => p.services.length > 0) && (
            <TotalBar total={subTotal} label="S'abonner via WhatsApp" monthly href={subWaUrl} onConfirm={saveSub} />
          )}
        </>
      )}

      {screen === "s-done" && (
        <ConfirmScreen
          title="Abonnement envoyé !"
          text="Votre demande d'abonnement a été préparée sur WhatsApp. Confirmez l'envoi du message pour l'activer."
          onHome={goHome}
        />
      )}

      {showPinGate && (
        <PinGate correctPin={adminPin}
          onClose={() => setShowPinGate(false)}
          onSuccess={() => { setShowPinGate(false); setShowSettings(true); }} />
      )}

      {showSettings && (
        <SettingsPanel prices={prices} waNumber={waNumber} trustCount={trustCount} adminPin={adminPin}
          bookedSlots={bookedSlots} loadSlotsForDate={loadSlotsForDate} adminToggleSlot={adminToggleSlot}
          onClose={() => setShowSettings(false)}
          onSave={(p, w, tc, pin) => { setPrices(p); setWaNumber(w); setTrustCount(tc); setAdminPin(pin); saveConfig(p, w, tc, pin); setShowSettings(false); }} />
      )}

      {toast && (
        <div style={{
          position: "absolute", bottom: 16, left: 16, right: 16, background: T.navy, color: T.white,
          padding: "12px 16px", borderRadius: 12, fontSize: 13.5, fontWeight: 600, textAlign: "center",
          boxShadow: "0 10px 24px -8px rgba(0,0,0,0.4)", zIndex: 60,
        }}>{toast}</div>
      )}
    </div>
  );
}

