function AddressForm({ data, setData, hideGps }) {
  const isCite = data.addrType === "cite";
  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        {["cite", "residence"].map((t) => (
          <button key={t} onClick={() => setData({ ...data, addrType: t })}
            style={{
              flex: 1, padding: "11px 8px", borderRadius: 12, fontWeight: 700, fontSize: 13.5,
              border: `1.5px solid ${data.addrType === t ? T.blue : T.mist}`,
              background: data.addrType === t ? "rgba(28,111,239,0.08)" : T.white,
              color: data.addrType === t ? T.blue : T.navy, cursor: "pointer",
            }}>
            {t === "cite" ? "Cité" : "Résidence"}
          </button>
        ))}
      </div>
      <TextField label={isCite ? "Nom de la cité" : "Nom de la résidence"} icon={<MapPin size={16} color={T.slate} />}
        placeholder={isCite ? "Ex: Cité SIR" : "Ex: Résidence Les Palmiers"}
        value={data.cityRes} onChange={(e) => setData({ ...data, cityRes: e.target.value })} />
      <TextField label={isCite ? "Numéro de villa" : "Numéro d'appartement"} icon={<Car size={16} color={T.slate} style={{ opacity: 0 }} />}
        placeholder={isCite ? "Ex: Villa 24" : "Ex: Appt B12"}
        value={data.unitNumber} onChange={(e) => setData({ ...data, unitNumber: e.target.value })} />
      {!hideGps && (
        <button onClick={() => {
          if (!navigator.geolocation) return;
          navigator.geolocation.getCurrentPosition(
            (pos) => setData({ ...data, gps: { lat: pos.coords.latitude, lng: pos.coords.longitude } }),
            () => {}
          );
        }} style={{
          display: "flex", alignItems: "center", gap: 8, background: "none", border: "none",
          color: T.blue, fontWeight: 600, fontSize: 13, cursor: "pointer", padding: "4px 0 18px",
        }}>
          <Crosshair size={15} /> {data.gps ? "Position ajoutée ✓" : "Utiliser ma position (facultatif)"}
        </button>
      )}
    </div>
  );
}

