function DatePicker({ booking, setBooking, bookedSlots }) {
  const days = Array.from({ length: 14 }, (_, i) => addDays(todayISO(), i));
  return (
    <div className="wg-scrollx" style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4 }}>
      {days.map((d) => {
        const { wd, dNum, mo } = dayLabel(d);
        const bookedList = bookedSlots[d] || [];
        const full = SLOTS.every((s) => bookedList.includes(s) || isSlotPast(d, s));
        const selected = booking.date === d;
        return (
          <button key={d} disabled={full}
            onClick={() => setBooking({ ...booking, date: d, time: null })}
            style={{
              minWidth: 56, borderRadius: 14, padding: "10px 6px", flexShrink: 0,
              border: `1.5px solid ${selected ? T.blue : T.mist}`,
              background: full ? "#F1F3F6" : selected ? T.gradient : T.white,
              color: full ? "#B7C0CC" : selected ? T.white : T.navy, cursor: full ? "not-allowed" : "pointer",
              display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
            }}>
            <span style={{ fontSize: 10.5, fontWeight: 600, opacity: 0.85 }}>{wd}</span>
            <span style={{ fontSize: 17, fontWeight: 800 }} className="wg-display">{dNum}</span>
            <span style={{ fontSize: 10, opacity: 0.85 }}>{mo}</span>
            {full && <span style={{ fontSize: 8, marginTop: 2 }}>Complet</span>}
          </button>
        );
      })}
    </div>
  );
}

