function PinGate({ correctPin, onClose, onSuccess }) {
  const [val, setVal] = useState("");
  const [error, setError] = useState(false);

  const submit = () => {
    if (val === correctPin) { onSuccess(); }
    else { setError(true); setVal(""); setTimeout(() => setError(false), 1400); }
  };

  return (
    <div style={{
      position: "absolute", inset: 0, background: "rgba(7,20,39,0.6)", zIndex: 55,
      display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
    }}>
      <div className="wg-anim" style={{
        background: T.white, borderRadius: 20, padding: "26px 22px", width: "100%", maxWidth: 300, textAlign: "center",
      }}>
        <div style={{
          width: 46, height: 46, borderRadius: 12, background: "#111827", margin: "0 auto 14px",
          display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          <Settings size={20} color={T.white} />
        </div>
        <div className="wg-display" style={{ fontSize: 15.5, fontWeight: 800, color: "#111827", marginBottom: 4 }}>Accès réservé</div>
        <div style={{ fontSize: 12.5, color: T.slate, marginBottom: 16 }}>Entrez le code admin pour ouvrir les réglages.</div>
        <input
          type="password" maxLength={20} value={val} autoFocus
          onChange={(e) => setVal(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && submit()}
          placeholder="••••"
          style={{
            width: "100%", textAlign: "center", fontSize: 20, letterSpacing: 6, padding: "12px 10px",
            border: `1.5px solid ${error ? T.danger : T.mist}`, borderRadius: 12, marginBottom: 14, color: "#111827",
          }} />
        {error && <div style={{ fontSize: 11.5, color: T.danger, marginTop: -8, marginBottom: 12 }}>Code incorrect</div>}
        <PrimaryButton onClick={submit} style={{ background: "#111827", boxShadow: "none" }}>Déverrouiller</PrimaryButton>
        <button onClick={onClose} style={{
          width: "100%", marginTop: 10, background: "none", border: "none", color: T.slate, fontSize: 12.5, fontWeight: 600, cursor: "pointer",
        }}>Annuler</button>
      </div>
    </div>
  );
}

function SettingsPanel({ prices, waNumber, trustCount, adminPin, bookedSlots, loadSlotsForDate, adminToggleSlot, onClose, onSave }) {
  const [p, setP] = useState(prices);
  const [w, setW] = useState(waNumber);
  const [tc, setTc] = useState(trustCount);
  const [pin, setPin] = useState(adminPin);
  const [slotDate, setSlotDate] = useState(todayISO());

  useEffect(() => { loadSlotsForDate(slotDate); }, [slotDate]);
  const dayBooked = bookedSlots[slotDate] || [];
  return (
    <div style={{
      position: "absolute", inset: 0, background: "rgba(7,20,39,0.55)", zIndex: 50,
      display: "flex", alignItems: "flex-end",
    }}>
      <div className="wg-anim" style={{
        background: T.white, width: "100%", maxHeight: "88%", overflowY: "auto",
        borderTopLeftRadius: 22, borderTopRightRadius: 22, padding: "18px 20px 26px",
      }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
          <div className="wg-display" style={{ fontSize: 16, fontWeight: 800, color: T.navy }}>Réglages WashGo</div>
          <button onClick={onClose} style={{ background: T.ice, border: "none", borderRadius: 10, width: 32, height: 32, cursor: "pointer" }}>
            <X size={16} color={T.navy} />
          </button>
        </div>

        <div style={{ fontSize: 12.5, fontWeight: 700, color: T.slate, marginBottom: 8 }}>CODE ADMIN (ACCÈS AUX RÉGLAGES)</div>
        <TextField label="Code admin" icon={<Settings size={16} color={T.slate} />}
          placeholder="Platini10@" value={pin} onChange={(e) => setPin(e.target.value)} />

        <div style={{ fontSize: 12.5, fontWeight: 700, color: T.slate, marginBottom: 8 }}>BADGE DE CONFIANCE (ACCUEIL)</div>
        <TextField label="Nombre de clients affiché (ex: 500)" icon={<Users size={16} color={T.slate} />}
          type="number" placeholder="500" value={tc} onChange={(e) => setTc(Number(e.target.value))} />

        <div style={{ fontSize: 12.5, fontWeight: 700, color: T.slate, marginBottom: 8 }}>NUMÉRO WHATSAPP DE RÉCEPTION</div>
        <TextField label="Format international, sans le +" icon={<Phone size={16} color={T.slate} />}
          placeholder="Ex: 2250700000000" value={w} onChange={(e) => setW(e.target.value)} />

        <div style={{ fontSize: 12.5, fontWeight: 700, color: T.slate, margin: "10px 0 8px" }}>GESTION DES CRÉNEAUX RÉSERVÉS</div>
        <label style={{ display: "block", marginBottom: 10 }}>
          <input type="date" value={slotDate} min={todayISO()}
            onChange={(e) => setSlotDate(e.target.value)}
            style={{ width: "100%", border: `1.5px solid ${T.mist}`, borderRadius: 12, padding: "11px 14px", fontSize: 14, color: T.navy }} />
        </label>
        <div style={{ fontSize: 11, color: T.slate, marginBottom: 10, lineHeight: 1.5 }}>
          Touchez un créneau pour le marquer Réservé ou Disponible. C'est ce statut, défini par vous, que voient les clients — pas la réservation en elle-même.
        </div>
        <div style={{ marginBottom: 8 }}>
          {SLOTS.map((s) => {
            const isBooked = dayBooked.includes(s);
            return (
              <button key={s} onClick={() => adminToggleSlot(slotDate, s)} style={{
                width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "10px 12px", borderRadius: 11, marginBottom: 6, cursor: "pointer", textAlign: "left",
                border: `1.5px solid ${isBooked ? "#FDE0E0" : T.mist}`,
                background: isBooked ? "#FEF6F6" : T.ice,
              }}>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 700, color: T.navy }}>{s}</div>
                  <div style={{ fontSize: 11, color: isBooked ? T.danger : "#7C8797", fontWeight: 600 }}>
                    {isBooked ? "Réservé" : "Disponible"}
                  </div>
                </div>
                <div style={{
                  borderRadius: 9, padding: "8px 12px", fontSize: 12, fontWeight: 700,
                  background: isBooked ? T.ice : "#111827", color: isBooked ? T.navy : T.white,
                  border: `1.5px solid ${isBooked ? T.mist : "#111827"}`,
                }}>
                  {isBooked ? "Libérer" : "Marquer réservé"}
                </div>
              </button>
            );
          })}
        </div>
        <div style={{ fontSize: 11, color: T.slate, background: T.ice, borderRadius: 10, padding: 10, marginBottom: 16, lineHeight: 1.5 }}>
          La réservation d'un client ne bloque plus le créneau automatiquement : vous confirmez vous-même après réception du message WhatsApp.
        </div>

        <div style={{ fontSize: 12.5, fontWeight: 700, color: T.slate, margin: "10px 0 8px" }}>TARIFS DES PRESTATIONS (FCFA)</div>
        {SERVICES.map((s) => (
          <div key={s.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10, gap: 10 }}>
            <span style={{ fontSize: 13, color: T.navy, fontWeight: 600 }}>{s.label}</span>
            <input type="number" value={p[s.key]} onChange={(e) => setP({ ...p, [s.key]: Number(e.target.value) })}
              style={{ width: 100, border: `1.5px solid ${T.mist}`, borderRadius: 10, padding: "8px 10px", fontSize: 13, textAlign: "right", color: T.navy }} />
          </div>
        ))}

        <div style={{ fontSize: 11, color: T.slate, background: T.ice, borderRadius: 10, padding: 10, margin: "8px 0 16px", lineHeight: 1.5 }}>
          Ces réglages sont partagés : toute personne utilisant cette application les verra et pourra les modifier.
        </div>

        <PrimaryButton onClick={() => onSave(p, w, tc, pin || "Platini10@")}>Enregistrer</PrimaryButton>
      </div>
    </div>
  );
}
